</svg>
        </div>

        <!-- Question -->
        <h2 class="text-2xl font-bold text-gray-900 mb-8">
            {{ $t('Have you completed any OJT or work experience?') }}
        </h2>

        <hr class="border-gray-200 my-8 w-full" />
        <!-- Buttons Row -->
        <div class="flex flex-row justify-center gap-4 w-full">
            <button
                @click="handleNo"
                :class="[
                    'text-center flex-1 max-w-[160px] py-6 rounded-xl border-2 font-semibold transition-all',
                    answer === 'no'
                        ? 'border-[#4984F6] text-[#4984F6] bg-blue-50'
                        : 'border-gray-200 bg-white text-gray-700 hover:border-[#4984F6] hover:text-[#4984F6]'
                ]"
            >
                {{ $t('No') }}
            </button>
            <button
                @click="handleYes"
                :class="[
                    'text-center flex-1 max-w-[160px] py-6 rounded-xl border-2 font-semibold transition-all',
                    answer === 'yes'
                        ? 'border-[#4984F6] text-[#4984F6] bg-blue-50'
                        : 'border-gray-200 bg-white text-gray-700 hover:border-[#4984F6] hover:text-[#4984F6]'
                ]"
            >
                {{ $t('Yes') }}
            </button>
        </div>
    </div>
</template>

<script>
export default {
    props: {
        portfolio: { type: Object, required: true }
    },

    data() {
        return {
            answer: this.portfolio.has_work_experience === true ? 'yes'
                  : this.portfolio.has_work_experience === false ? 'no' : null
        };
    },

    methods: {
        handleYes() {
            this.answer = 'yes';
            this.$emit('update', { has_work_experience: true });
            setTimeout(() => this.$emit('yes'), 200); 
        },
        handleNo() {
            this.answer = 'no';
            this.$emit('update', { has_work_experience: false });
            setTimeout(() => this.$emit('no'), 200); 
        }
    }
};
</script>
